mapper.update:
UPDATE cart_items
SET
    quantity = #{quantity},
    updated_at = NOW()
WHERE id = #{cart_id}
    AND user_id = #{user_id}

mapper.delete:
DELETE FROM cart_items
WHERE id = #{cart_id}
AND user_id = #{user_id}

mapper.select:
SELECT COUNT(*)
FROM cart_items
WHERE user_id = #{user_id}
